<?php $pageTitle='New project'; $activePage='projects'; require_once __DIR__.'/../includes/header.php'; require_permission('manage_projects'); $clients=$pdo->query('SELECT id,company FROM clients WHERE status="active" ORDER BY company')->fetchAll(); $managers=$pdo->query('SELECT id,name FROM users WHERE status="active" ORDER BY name')->fetchAll(); if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf']??null)){flash('danger','Security token expired.');}else{$statement=$pdo->prepare('INSERT INTO projects(client_id,manager_id,name,description,start_date,due_date,budget,status,priority,technologies,repository_url,development_url,staging_url,production_url) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$statement->execute([(int)$_POST['client_id'],(int)$_POST['manager_id']?:null,trim($_POST['name']),trim($_POST['description']),$_POST['start_date'],$_POST['due_date'],(float)$_POST['budget'],$_POST['status'],$_POST['priority'],trim($_POST['technologies']),trim($_POST['repository_url']),trim($_POST['development_url']),trim($_POST['staging_url']),trim($_POST['production_url'])]);$id=(int)$pdo->lastInsertId();record_activity('Created project','project',$id);flash('success','Project created.');redirect('projects/view.php?id='.$id);}} ?><div class="mb-4"><span class="section-kicker">New engagement</span><h2 class="mt-2">Create a project</h2></div><form method="post" class="panel form-panel"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-8"><label class="form-label">Project name<input name="name" class="form-control" required placeholder="e.g. Northstar platform"></label></div><div class="col-md-4"><label class="form-label">Client<select name="client_id" class="form-select" required><option value="">Choose client</option><?php foreach($clients as $client): ?><option value="<?= $client['id'] ?>"><?= e($client['company']) ?></option><?php endforeach; ?></select></label></div><div class="col-md-6"><label class="form-label">Project manager<select name="manager_id" class="form-select"><option value="">Unassigned</option><?php foreach($managers as $manager): ?><option value="<?= $manager['id'] ?>"><?= e($manager['name']) ?></option><?php endforeach; ?></select></label></div><div class="col-md-3"><label class="form-label">Status<select name="status" class="form-select"><?php foreach(['Planning','Not Started','In Progress','On Hold','Under Review','Testing','Completed','Cancelled'] as $status): ?><option><?= e($status) ?></option><?php endforeach; ?></select></label></div><div class="col-md-3"><label class="form-label">Priority<select name="priority" class="form-select"><?php foreach(['Low','Medium','High','Critical'] as $priority): ?><option><?= e($priority) ?></option><?php endforeach; ?></select></label></div><div class="col-md-4"><label class="form-label">Start date<input name="start_date" type="date" class="form-control" required></label></div><div class="col-md-4"><label class="form-label">Expected completion<input name="due_date" type="date" class="form-control" required></label></div><div class="col-md-4"><label class="form-label">Budget<input name="budget" type="number" step="0.01" class="form-control" value="0"></label></div><div class="col-12"><label class="form-label">Technologies<input name="technologies" class="form-control" placeholder="PHP, MySQL, JavaScript"></label></div><div class="col-12"><label class="form-label">Description<textarea name="description" class="form-control" rows="4"></textarea></label></div><div class="col-md-6"><label class="form-label">Repository URL<input name="repository_url" type="url" class="form-control"></label></div><div class="col-md-6"><label class="form-label">Development URL<input name="development_url" type="url" class="form-control"></label></div><div class="col-md-6"><label class="form-label">Staging URL<input name="staging_url" type="url" class="form-control"></label></div><div class="col-md-6"><label class="form-label">Production URL<input name="production_url" type="url" class="form-control"></label></div></div><div class="mt-4 d-flex gap-2"><button class="btn btn-primary">Create project</button><a href="<?= url('projects/') ?>" class="btn btn-light">Cancel</a></div></form><?php require_once __DIR__.'/../includes/footer.php'; ?>
